<?php

namespace Tests\Feature;

use App\Models\Company;
use App\Models\Record;
use App\Models\RecordActivityLog;
use App\Models\RecordClassification;
use App\Models\RecordIndex;
use App\Services\CompanyContext;
use App\Services\Records\RecordFilingService;
use App\Services\Records\RecordIntakeService;
use App\Support\RecordNumberGenerator;
use Tests\Support\FakeUploads;
use Tests\TestCase;

/**
 * The Record ID — REC-2026-001285 — and the settings behind it.
 *
 * A second identifier, not a replacement. The Document Reference is still
 * generated by ORDO at filing and nothing here touches it; what is new is a
 * readable, ordered number a person configures.
 *
 * The property that matters most is that no two records share a number, because
 * the counter lives on the company row and filing is a transaction. The tests
 * below are mostly about that.
 */
class RecordNumberingTest extends TestCase
{
    use FakeUploads;

    private Company $company;

    private RecordNumberGenerator $numbers;

    protected function setUp(): void
    {
        parent::setUp();

        $this->company = $this->seedTenantAndCompany();
        $this->actingInCompany($this->company);
        $this->numbers = $this->app->make(RecordNumberGenerator::class);

        $classification = new RecordClassification;
        $classification->forceFill([
            'tenant_id' => $this->company->tenant_id,
            'company_id' => $this->company->id,
            'code' => '301',
            'name' => 'Entity & Ownership',
            'is_active' => true,
        ])->save();

        $index = new RecordIndex;
        $index->forceFill([
            'tenant_id' => $this->company->tenant_id,
            'company_id' => $this->company->id,
            'record_classification_id' => $classification->id,
            'code' => '301-6',
            'name' => 'GIS',
            'sort_order' => 0,
            'is_active' => true,
        ])->save();
    }

    // ----------------------------------------------------------- the format

    public function test_the_number_is_assembled_as_the_reference_mock_does(): void
    {
        $this->configure(['prefix' => 'REC', 'digits' => 6, 'next' => 1285, 'includeYear' => true]);

        $this->assertSame('REC-'.now()->format('Y').'-001285', $this->numbers->preview($this->company->refresh()));
    }

    public function test_the_year_is_omitted_when_it_is_switched_off(): void
    {
        $this->configure(['prefix' => 'REC', 'digits' => 6, 'next' => 1285, 'includeYear' => false]);

        $this->assertSame('REC-001285', $this->numbers->preview($this->company->refresh()));
    }

    public function test_the_sequence_is_padded_to_the_chosen_width(): void
    {
        foreach ([3, 4, 6, 8, 10] as $digits) {
            $this->configure(['prefix' => 'REC', 'digits' => $digits, 'next' => 7, 'includeYear' => false]);

            $this->assertSame(
                'REC-'.str_pad('7', $digits, '0', STR_PAD_LEFT),
                $this->numbers->preview($this->company->refresh()),
            );
        }
    }

    public function test_the_prefix_is_used_verbatim(): void
    {
        $this->configure(['prefix' => 'ACME-DOC', 'digits' => 4, 'next' => 12, 'includeYear' => false]);

        $this->assertSame('ACME-DOC-0012', $this->numbers->preview($this->company->refresh()));
    }

    // --------------------------------------------------------- at filing

    public function test_a_filed_record_is_issued_a_record_id(): void
    {
        $this->configure(['prefix' => 'REC', 'digits' => 6, 'next' => 1, 'includeYear' => true]);

        $record = $this->filedRecord();

        $this->assertSame('REC-'.now()->format('Y').'-000001', $record->record_number);
    }

    public function test_the_document_reference_is_still_generated_separately(): void
    {
        $record = $this->filedRecord();

        $this->assertNotNull($record->document_reference);
        $this->assertSame(5, strlen((string) $record->document_reference));
        // Two identifiers, neither derived from the other.
        $this->assertNotSame($record->record_number, $record->document_reference);
    }

    public function test_the_sequence_advances_and_never_repeats(): void
    {
        $this->configure(['prefix' => 'REC', 'digits' => 4, 'next' => 1, 'includeYear' => false]);

        $issued = [];

        for ($i = 0; $i < 6; $i++) {
            $issued[] = $this->filedRecord()->record_number;
        }

        $this->assertSame([
            'REC-0001', 'REC-0002', 'REC-0003', 'REC-0004', 'REC-0005', 'REC-0006',
        ], $issued);

        $this->assertCount(6, array_unique($issued), 'A number was issued twice.');
    }

    /**
     * The counter is left after the number just issued, so the tab's example is
     * always the *next* one rather than a repeat of the last.
     */
    public function test_the_counter_is_left_past_the_number_issued(): void
    {
        $this->configure(['prefix' => 'REC', 'digits' => 4, 'next' => 1285, 'includeYear' => false]);

        $this->assertSame('REC-1285', $this->filedRecord()->record_number);
        $this->assertSame(1286, (int) $this->company->refresh()->record_next_sequence);
        $this->assertSame('REC-1286', $this->numbers->preview($this->company->refresh()));
    }

    /**
     * Two companies number independently. The counter is on the company row, so
     * one company's filings cannot consume another's sequence.
     */
    public function test_each_company_numbers_from_its_own_counter(): void
    {
        $this->configure(['prefix' => 'MINE', 'digits' => 4, 'next' => 1, 'includeYear' => false]);
        $this->assertSame('MINE-0001', $this->filedRecord()->record_number);

        $other = $this->seedSecondCompany($this->company);

        // The second company needs its own scheme before anything can be filed
        // into it — the filing service refuses a Classification belonging to
        // anybody else, which is the point.
        $classification = new RecordClassification;
        $classification->forceFill([
            'tenant_id' => $other->tenant_id,
            'company_id' => $other->id,
            'code' => '301',
            'name' => 'Entity & Ownership',
            'is_active' => true,
        ])->save();

        $index = new RecordIndex;
        $index->forceFill([
            'tenant_id' => $other->tenant_id,
            'company_id' => $other->id,
            'record_classification_id' => $classification->id,
            'code' => '301-6',
            'name' => 'GIS',
            'sort_order' => 0,
            'is_active' => true,
        ])->save();

        $other->forceFill([
            'record_prefix' => 'THEIRS',
            'record_sequence_digits' => 4,
            'record_next_sequence' => 500,
            'record_include_year' => false,
        ])->save();

        $this->actingInCompany($other->refresh());

        $this->assertSame('THEIRS-0500', $this->filedRecord()->record_number);
    }

    /**
     * The edge case the settings make possible.
     *
     * An operator can set Next Sequence below what has already been issued. That
     * must not collide and must not fail the filing — the generator walks
     * forward to the first free number instead.
     */
    public function test_a_sequence_set_backwards_skips_to_the_first_free_number(): void
    {
        $this->configure(['prefix' => 'REC', 'digits' => 4, 'next' => 1, 'includeYear' => false]);

        foreach (['REC-0001', 'REC-0002', 'REC-0003'] as $_) {
            $this->filedRecord();
        }

        $this->configure(['prefix' => 'REC', 'digits' => 4, 'next' => 1, 'includeYear' => false]);

        $record = $this->filedRecord();

        $this->assertSame('REC-0004', $record->record_number);
        $this->assertSame(5, (int) $this->company->refresh()->record_next_sequence);
    }

    /**
     * Changing the prefix never rewrites what was already issued.
     */
    public function test_changing_the_settings_does_not_rewrite_existing_numbers(): void
    {
        $this->configure(['prefix' => 'REC', 'digits' => 4, 'next' => 1, 'includeYear' => false]);

        $first = $this->filedRecord()->record_number;

        $this->configure(['prefix' => 'ACME', 'digits' => 6, 'next' => 1, 'includeYear' => true]);

        $second = $this->filedRecord()->record_number;

        $this->assertSame('REC-0001', $first);
        $this->assertSame('ACME-'.now()->format('Y').'-000001', $second);
    }

    /**
     * Records filed before this feature existed carry no Record ID, and inventing
     * one would mint identifiers that were never issued.
     */
    public function test_an_older_record_carries_no_record_id(): void
    {
        $record = $this->filedRecord();

        $record->forceFill(['record_number' => null])->save();

        $this->assertNull($record->refresh()->record_number);
        // And the next filing still starts cleanly rather than colliding.
        $this->assertSame('REC-'.now()->format('Y').'-000002', $this->filedRecord()->record_number);
    }

    // --------------------------------------------------------- the save path

    public function test_the_settings_save_and_redirect_back_to_the_tab(): void
    {
        $response = $this->put(route('records.numbering.update'), [
            'record_prefix' => 'ACME',
            'record_sequence_digits' => 4,
            'record_next_sequence' => 1285,
            'record_include_year' => 'yes',
        ]);

        $response->assertRedirect();
        $response->assertSessionHas('setup_tab', 'numbering');

        $company = $this->company->refresh();

        $this->assertSame('ACME', $company->record_prefix);
        $this->assertSame(4, $company->record_sequence_digits);
        $this->assertSame(1285, $company->record_next_sequence);
        $this->assertTrue($company->record_include_year);
    }

    public function test_the_year_can_be_switched_off(): void
    {
        $this->put(route('records.numbering.update'), [
            'record_prefix' => 'ACME',
            'record_sequence_digits' => 4,
            'record_next_sequence' => 1285,
            'record_include_year' => 'no',
        ])->assertRedirect();

        $this->assertFalse($this->company->refresh()->record_include_year);
    }

    /**
     * The mock's own clamps, applied by validation rather than silently.
     */
    public function test_the_settings_are_bounded_as_the_mock_bounds_them(): void
    {
        $response = $this->put(route('records.numbering.update'), [
            'record_prefix' => 'A-very-long-prefix-indeed',
            'record_sequence_digits' => 2,
            'record_next_sequence' => 0,
            'record_include_year' => 'perhaps',
        ]);

        $response->assertSessionHasErrors(['record_prefix', 'record_sequence_digits', 'record_next_sequence', 'record_include_year']);
    }

    /**
     * Changing the prefix changes what every future record will be called, so it
     * is recorded. The other setup screens do not audit; this one does.
     */
    public function test_changing_the_numbering_is_recorded_in_the_trail(): void
    {
        $this->put(route('records.numbering.update'), [
            'record_prefix' => 'ACME',
            'record_sequence_digits' => 4,
            'record_next_sequence' => 1285,
            'record_include_year' => 'yes',
        ])->assertRedirect();

        $entry = RecordActivityLog::query()
            ->where('action', 'record.numbering_changed')
            ->where('company_id', $this->company->id)
            ->firstOrFail();

        // The snapshot is of what was there *before* the save — the company's
        // default REC prefix — not the value just written. That is the whole
        // point of recording it.
        $this->assertSame('REC', $entry->properties['before']['prefix']);
        $this->assertSame('ACME', $this->company->refresh()->record_prefix);
        $this->assertStringContainsString('ACME', $entry->description);
    }

    public function test_an_untouched_setting_still_records_the_change(): void
    {
        $this->put(route('records.numbering.update'), [
            'record_prefix' => 'REC',
            'record_sequence_digits' => 6,
            'record_next_sequence' => 1,
            'record_include_year' => 'yes',
        ])->assertRedirect();

        $this->assertDatabaseHas('record_activity_logs', [
            'company_id' => $this->company->id,
            'action' => 'record.numbering_changed',
        ]);
    }

    // ---------------------------------------------------------------- helpers

    /**
     * @param  array{prefix?: string, digits?: int, next?: int, includeYear?: bool}  $settings
     */
    private function configure(array $settings): void
    {
        // Written through a fresh instance on purpose. Filing advances
        // record_next_sequence through its own model, so $this->company holds a
        // stale copy; forceFill() on it would find nothing dirty and save()
        // would write nothing, which is the exact bug this test would otherwise
        // be asserting around rather than against.
        Company::query()->whereKey($this->company->id)->update([
            'record_prefix' => $settings['prefix'] ?? 'REC',
            'record_sequence_digits' => $settings['digits'] ?? 6,
            'record_next_sequence' => $settings['next'] ?? 1,
            'record_include_year' => $settings['includeYear'] ?? true,
        ]);

        $this->company->refresh();
    }

    private function filedRecord(): Record
    {
        $intake = $this->app->make(RecordIntakeService::class)
            ->createIntakeItem([$this->fakePdf('minutes.pdf', 16)]);

        [$classification, $index] = $this->scheme();

        return $this->app->make(RecordFilingService::class)->file($intake, [
            'record_classification_id' => $classification->id,
            'record_index_id' => $index->id,
        ])->refresh();
    }

    /**
     * The acting company's scheme.
     *
     * Read from the context rather than from $this->company, because the
     * per-company test acts in a second company and the filing service refuses a
     * Classification belonging to anybody else.
     *
     * @return array{0: RecordClassification, 1: RecordIndex}
     */
    private function scheme(): array
    {
        $companyId = $this->app->make(CompanyContext::class)->id();

        $classification = RecordClassification::query()
            ->where('company_id', $companyId)->firstOrFail();

        $index = RecordIndex::query()
            ->where('company_id', $companyId)->firstOrFail();

        return [$classification, $index];
    }
}
